using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketsController : ControllerBase
{
    private readonly TicketClassifierService _classifier;

    public TicketsController(TicketClassifierService classifier)
    {
        _classifier = classifier;
    }

    [HttpPost("classify")]
    public ActionResult<TicketPredictionResponse> Classify([FromBody] TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _classifier.Predict(ticketData);

        return Ok(new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = prediction.Score.Max(),
            Scores = new Dictionary<string, float>
            {
                ["Billing"] = prediction.Score.ElementAtOrDefault(0),
                ["General"] = prediction.Score.ElementAtOrDefault(1),
                ["Technical"] = prediction.Score.ElementAtOrDefault(2)
            }
        });
    }

    [HttpGet("metrics")]
    public ActionResult<EvaluationMetrics> GetMetrics()
    {
        return Ok(_classifier.Metrics);
    }
}

public sealed class TicketPredictionResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public float Confidence { get; set; }
    public Dictionary<string, float> Scores { get; set; } = new();
}

