using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketClassifierService
{
    private readonly MLContext _mlContext = new(seed: 42);
    private readonly ILogger<TicketClassifierService> _logger;
    private ITransformer _model = null!;
    private PredictionEngine<TicketData, TicketPrediction> _predictionEngine = null!;
    private EvaluationMetrics _metrics = null!;
    private string[] _labelNames = [];

    public TicketClassifierService(ILogger<TicketClassifierService> logger)
    {
        _logger = logger;
    }

    public EvaluationMetrics Metrics => _metrics;
    public string[] LabelNames => _labelNames;

    public void TrainAndEvaluate(string dataPath)
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Text
                .FeaturizeText("SubjectFeatures", nameof(TicketData.Subject))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(split.TrainSet);

        // Extract label names from the trained model's key-value mapping
        var schema = _model.GetOutputSchema(split.TrainSet.Schema);
        var labelColumn = schema["Label"];
        var keyType = labelColumn.Type as Microsoft.ML.Data.KeyDataViewType;
        VBuffer<ReadOnlyMemory<char>> keyValues = default;
        labelColumn.GetKeyValues(ref keyValues);
        _labelNames = keyValues.DenseValues().Select(v => v.ToString()).ToArray();

        var predictions = _model.Transform(split.TestSet);
        var mlMetrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        static double sanitize(double v) => double.IsNaN(v) || double.IsInfinity(v) ? 0.0 : v;

        _metrics = new EvaluationMetrics
        {
            MacroAccuracy = sanitize(mlMetrics.MacroAccuracy),
            MicroAccuracy = sanitize(mlMetrics.MicroAccuracy),
            LogLoss = sanitize(mlMetrics.LogLoss),
            LogLossReduction = sanitize(mlMetrics.LogLossReduction),
            PerClassLogLoss = mlMetrics.PerClassLogLoss.Select(x => (float)sanitize(x)).ToArray(),
            ConfusionMatrix = mlMetrics.ConfusionMatrix.GetFormattedConfusionTable()
        };

        _logger.LogInformation(
            "Model trained — MacroAccuracy: {Macro:F4}, MicroAccuracy: {Micro:F4}, LogLoss: {LogLoss:F4}",
            _metrics.MacroAccuracy, _metrics.MicroAccuracy, _metrics.LogLoss);

        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);
    }

    public TicketPrediction Predict(TicketData ticket) => _predictionEngine.Predict(ticket);
}

public sealed class EvaluationMetrics
{
    public double MacroAccuracy { get; set; }
    public double MicroAccuracy { get; set; }
    public double LogLoss { get; set; }
